def calculate_S(N):
    """Calculates S = sum_{a=1}^{N} sum_{b=1}^{N} floor(ab / (N+1))"""
    S = 0
    N_plus_1 = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // N_plus_1
    return S

def calculate_T(N):
    """Calculates the target sum T = (N^3 - N^2 + 2) / 4"""
    return (N**3 - N**2 + 2) / 4

